-- Demo data for local development only (scripts/dev/setup.sh). Fictional shops on .example domains.
-- Never run against the real project. Publishing needs the pipeline role (0006 trigger).
set role pipeline;
reset role;
select 2026, 44, '2026-week-44', 'Vijf makers van hout en klei', 'Deze week: shops die alles zelf maken, van eiken tafels tot gedraaide vazen.',
  E'## Hout uit eigen werkplaats\n\n[Houtatelier Noord](/webshop/houtatelier-noord) maakt tafels op maat in Groningen.\n\n## Klei en glas\n\n[Keramiek Studio Klei](/webshop/keramiek-studio-klei) draait vazen in Utrecht. **Mondgeblazen** lampen vind je bij [Glasblazerij Zuid](/webshop/glasblazerij-zuid).',
  array(select id from public.shops where slug in ('houtatelier-noord', 'keramiek-studio-klei', 'glasblazerij-zuid')), '{}'::jsonb, 'published', now() - interval '3 days'
on conflict (slug) do nothing;
